/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Track changes related to prices and add entry to Price Change tracking table for later processing
/// </summary>
using System.ComponentModel.Composition;

[Export(identifierStr(Dynamics.AX.Application.METPriceChangeTrack))]
[ExportMetadata(enumStr(METPriceChangeType), enumLiteralStr(METPriceChangeType, TradeAgreement))]
public class METPriceChangeTrackTradeAgreement extends METPriceChangeTrack
{
    PriceDiscAdmTable           priceDiscAdmTable;
    METPriceAttributeEnabled    priceAttributeEnabled;
    TransDate                   todayDate;

}

Method.Source:
/// <summary>
/// Initialise the instance
/// </summary>
/// <param name = "_common">Table record</param>
public void initInstanceSource(Common _common)
{
    this.setInternals(_Common);
}

/// <summary>
/// Set internal variables
/// </summary>
/// <param name = "_common">Table record</param>
public void setInternals(Common _common)
{
    priceDiscAdmTable       = _common as PriceDiscAdmTable;
    priceAttributeEnabled   = priceDiscAdmTable.priceDiscPriceAttributeEnable();
    todayDate = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimezone());
}

/// <summary>
/// Get the Price change type
/// </summary>
/// <returns>Price change type</returns>
public METPriceChangeType getPriceChangeType()
{
    return METPriceChangeType::TradeAgreement;
}

    /// <summary>
    /// Process the base record that triggered the change
    /// </summary>
    public void processSource()
    {
        PriceDiscAdmTrans       priceDiscAdmTrans;
        RecordInsertList        priceChangeTrackingList;

        if( priceDiscAdmTable.Posted && priceDiscAdmTable.DefaultRelation == PriceType::PriceSales)
        {
            priceChangeTrackingList = new RecordInsertList(tableNum(METPriceChangeTracking));

            if(priceAttributeEnabled)
            {
                while select priceDiscAdmTrans
                    where   priceDiscAdmTrans.JournalNum    == priceDiscAdmTable.JournalNum
                {
                    this.setStandardValues(priceDiscAdmTrans);
                    
                    priceChangeTracking.PriceAttributeEnabled           = priceAttributeEnabled;
                    priceChangeTracking.PricingAttributeGroupHeader     = priceDiscAdmTrans.displayPricingAttributeGroupNameHeader();
                    priceChangeTracking.PricingAttributeDetailsHeader   = priceDiscAdmTrans.pricingAttributeDetailsHeader();
                    priceChangeTracking.PricingAttributeGroupLine       = priceDiscAdmTrans.displayPricingAttributeGroupNameLine();
                    priceChangeTracking.PricingAttributeDetailsLine     = priceDiscAdmTrans.pricingAttributeDetailsLine();
                    priceChangeTracking.PricingRuleHeader               = priceDiscAdmTrans.PricingRuleHeader;
                    priceChangeTracking.PricingRuleLine                 = priceDiscAdmTrans.PricingRuleLine;

                    priceChangeTrackingList.add(priceChangeTracking);
                    
                }
            }
            else
            {
                while select priceDiscAdmTrans
                    where   priceDiscAdmTrans.JournalNum    == priceDiscAdmTable.JournalNum
                    &&      priceDiscAdmTrans.ItemCode      == PriceDiscProductCodeType::Table
                    &&     (priceDiscAdmTrans.AccountCode   == PriceDiscPartyCodeType::GroupId || priceDiscAdmTrans.AccountCode  == PriceDiscPartyCodeType::Table)
                {
                    this.setStandardValues(priceDiscAdmTrans);
                    
                    priceChangeTracking.PriceDiscPartyCode      = priceDiscAdmTrans.AccountCode;
                    priceChangeTracking.PriceDiscAccountRelation = priceDiscAdmTrans.AccountRelation;
                    priceChangeTracking.ItemId                  = priceDiscAdmTrans.itemCode == PriceDiscProductCodeType::Table ? priceDiscAdmTrans.ItemRelation : blankValue;
                    
                    priceChangeTrackingList.add(priceChangeTracking);
                }
            }
            ttsbegin;
            priceChangeTrackingList.insertDatabase();
            ttscommit;
        }
    }

/// <summary>
/// Set standard values
/// </summary>
/// <param name = "_priceDiscAdmTrans">Trade agreement line</param>
public void setStandardValues(PriceDiscAdmTrans _priceDiscAdmTrans)
{
    priceChangeTracking.clear();
    this.setCommonValues(_priceDiscAdmTrans);
    priceChangeTracking.PriceDiscJournalNum     = _priceDiscAdmTrans.JournalNum;
    priceChangeTracking.PriceDiscLineNum        = _priceDiscAdmTrans.LineNum;
    priceChangeTracking.FromDate                = _priceDiscAdmTrans.FromDate ? _priceDiscAdmTrans.FromDate : todayDate;
    priceChangeTracking.ToDate                  = _priceDiscAdmTrans.ToDate;
    priceChangeTracking.InventSiteId            = InventDim::find(_priceDiscAdmTrans.inventDimId).InventSiteId;
    priceChangeTracking.UnitId                  = _priceDiscAdmTrans.UnitId;
    priceChangeTracking.Price                   = _priceDiscAdmTrans.amount;
    priceChangeTracking.PriceQty                = _priceDiscAdmTrans.priceUnit;
    priceChangeTracking.QuantityAmountFrom      = _priceDiscAdmTrans.QuantityAmountFrom;
    priceChangeTracking.QuantityAmountTo        = _priceDiscAdmTrans.QuantityAmountTo;
}

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void processChange()
    {
        priceDataFeedCount = 0;
        priceDataFeedList = new RecordInsertList(tableNum(METPriceDataFeed));

        if(priceChangeTracking.PriceAttributeEnabled)
        {
            this.processChangeAttr();
        }
        else
        {
            this.processChangeStd();
        }

        if(priceDataFeedCount)
        {
            ttsbegin;
            priceDataFeedList.insertDatabase();
            ttscommit;
        }
    }

/// <summary>
/// Process the Change tracking record
/// </summary>
public void processChangeStd()
{
    switch(priceChangeTracking.PriceDiscPartyCode)
    {
        case PriceDiscPartyCodeType::Table:
            this.processChangeSingle();
            break;
        case PriceDiscPartyCodeType::GroupId:
            this.processChangeGroup();
            break;
    }
}

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void processChangeAttr()
    {
        GUPPricingRuleCopy  pricingRuleCopyCustHeader, pricingRuleCopy;
        Query               custPreviewQuery;
        QueryRun            custPreviewQueryRun;
        Query               productPreviewQuery;
        QueryRun            productPreviewQueryRun;
        CustTable           custTable;
        InventTable         inventTable;
        Set                 custAccountSet, inventItemSet;
        QueryBuildDataSource    qbds;
        QueryBuildRange         qbr;


        pricingRuleCopyCustHeader.initFromPricingRule(GUPPricingRule::find(priceChangeTracking.pricingRuleHeader));
        pricingRuleCopy.initFromPricingRule(GUPPricingRule::find(priceChangeTracking.PricingRuleLine));

        if (pricingRuleCopyCustHeader.PriceAttributeGroupName != '')
        {
            //build customer list
            custPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(pricingRuleCopyCustHeader).build();

            qbds = SysQuery::findOrCreateDataSource(custPreviewQuery, tableNum(GUPPricingRuleExclusionCopy), tableNum(CustTable));
            qbds.joinMode(joinMode::NoExistsJoin);
            qbds.addLink(fieldNum(CustTable, AccountNum),fieldNum(GUPPricingRuleExclusionCopy, Exclusion));

            qbr = SysQuery::findOrCreateRange(qbds, fieldNum(GUPPricingRuleExclusionCopy, RuleId));
            qbr.value(queryValue(pricingRuleCopyCustHeader.RuleId));

            custPreviewQueryRun = new QueryRun(custPreviewQuery);

            custAccountSet = new Set(Types::String);

            while(custPreviewQueryRun.next())
            {
                custTable = custPreviewQueryRun.get(tableNum(CustTable));

                custAccountSet.add(custTable.AccountNum);
                
            }
        }

        if(pricingRuleCopy.PriceAttributeGroupName != '')
        {
            //build item list
            productPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(pricingRuleCopy).build();

            qbds = SysQuery::findOrCreateDataSource(productPreviewQuery, tableNum(GUPPricingRuleExclusionCopy), tableNum(InventTable));
            qbds.joinMode(joinMode::NoExistsJoin);
            qbds.addLink(fieldNum(InventTable,ItemId),fieldNum(GUPPricingRuleExclusionCopy, Exclusion));

            qbr = SysQuery::findOrCreateRange(qbds, fieldNum(GUPPricingRuleExclusionCopy, RuleId));
            qbr.value(queryValue(pricingRuleCopy.RuleId));

            productPreviewQueryRun = new QueryRun(productPreviewQuery);

            inventItemSet = new Set(Types::String);

            while(productPreviewQueryRun.next())
            {
                inventTable = productPreviewQueryRun.get(tableNum(InventTable));

                inventItemSet.add(inventTable.ItemID);
                
            }
        }

        this.processChangeMulti(custAccountSet, inventItemSet);
    }

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void processChangeSingle()
    {
        boolean             validityCheck = true;
        
        //1. Execute the Item/Site validity check
        validityCheck = this.ItemSiteValidation(priceChangeTracking.ItemId, priceChangeTracking.InventSiteId);

        if(validityCheck)
        {
            //2. Execute the Customer/Item validity check
            validityCheck = this.CustomerItemValidation(priceChangeTracking.priceDiscAccountRelation, priceChangeTracking.ItemId);
        }

        if(validityCheck)
        {
            this.createPriceDataFeed(priceChangeTracking);
            priceDataFeedList.add(priceDataFeed);

            priceDataFeedCount++;
        }
    }

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void processChangeGroup()
    {
        CustTable           custTable;
        Set                 custAccountSet, inventItemSet;

        custAccountSet  = new Set(Types::String);
        inventItemSet   = new Set(Types::String);

        while select AccountNum
            from    custTable
            where   custTable.PriceGroup == priceChangeTracking.PriceDiscAccountRelation
        {
            custAccountSet.add(custTable.AccountNum);
        }

        inventItemSet.add(priceChangeTracking.ItemId);

        this.processChangeMulti(custAccountSet, inventItemSet);
    }

    /// <summary>
    /// Process the Change tracking record
    /// </summary>    
    /// <param name = "_custAccountSet">Customer Accounts</param>
    /// <param name = "_inventItemSet">Items</param>
    public void processChangeMulti(Set _custAccountSet, Set _inventItemSet)
    {
        SetEnumerator       custAccountEnumerator, inventItemEnumerator;
        AccountNum          custAccount;
        ItemId              inventItem;
        Set                 custAccountSet, inventItemSet;

        custAccountSet  = _custAccountSet;
        inventItemSet   = _inventItemSet;

        inventItemEnumerator = inventItemSet.getEnumerator();

        boolean             validityCheck;
        METPriceChangeTracking  priceChangeTrackingUpdated;

        while(inventItemEnumerator.moveNext())
        {
            validityCheck = true;

            inventItem  = inventItemEnumerator.current();

            //1. Execute the Item/Site validity check
            validityCheck = this.ItemSiteValidation(inventItem, priceChangeTracking.InventSiteId);

            if(validityCheck)
            {
                custAccountEnumerator = custAccountSet.getEnumerator();
                
                while(custAccountEnumerator.moveNext())
                {
                    custAccount = custAccountEnumerator.current();

                    //2. Execute the Customer/Item validity check
                    validityCheck = this.CustomerItemValidation(custAccount, inventItem);

                    if(validityCheck)
                    {
                        priceChangeTrackingUpdated.data(priceChangeTracking);
                        priceChangeTrackingUpdated.PriceDiscAccountRelation = custAccount;
                        priceChangeTrackingUpdated.ItemId                   = inventItem;
                        priceChangeTrackingUpdated.RecId                    = 0;
                        
                        this.createPriceDataFeed(priceChangeTrackingUpdated);

                        priceDataFeedList.add(priceDataFeed);

                        priceDataFeedCount++;
                    }
                }
            }
        }
    }
